{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/dish-showcase.json
    A showcase of dishes: each card is one link to the dish page (picture, badge, name, weight, summary, price and an arrow). No cart here. Axes: cols (3, 4), ratio (4/3, 1/1), tone.
    Props (p): id, title, lead, dishes, empty, labels, cols, ratio, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_dishes = ($p['dishes'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_cols = ($p['cols'] ?? '3')}
{var $v_ratio = ($p['ratio'] ?? '4/3')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_12}
  {if og_t(og_eq(og_len($v_dishes), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'star', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_11}
      {foreach og_l($v_dishes) as $v_d}
        {capture $c_10}
          {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_d, ['name']), 'ratio' => $v_ratio]])|noescape}
          {capture $c_9}
            {if og_t(og_get($v_d, ['badge']))}
              {capture $c_1}
                {=og_text(og_get($v_d, ['badge']))}
              {/capture}
              {=og_include('compose/Badge.latte', ['variant' => 'secondary', 'size' => 'sm', 'class' => 'w-fit', 'children' => (string) $c_1])|noescape}
            {/if}
            {capture $c_4}
              {capture $c_2}
                {=og_text(og_get($v_d, ['name']))}
              {/capture}
              {=og_include('compose/Inline.latte', ['class' => 'text-lg font-semibold', 'children' => (string) $c_2])|noescape}
              {capture $c_3}
                {=og_text(og_get($v_d, ['weight']))}
              {/capture}
              {=og_include('compose/Inline.latte', ['class' => 'text-sm text-muted-foreground', 'children' => (string) $c_3])|noescape}
            {/capture}
            {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'baseline', 'justify' => 'between', 'children' => (string) $c_4])|noescape}
            {capture $c_5}
              {=og_text(og_get($v_d, ['summary']))}
            {/capture}
            {=og_include('compose/Inline.latte', ['class' => 'text-sm font-normal text-muted-foreground', 'children' => (string) $c_5])|noescape}
            {capture $c_8}
              {capture $c_6}
                {=og_text(og_money(og_get($v_d, ['price']), og_get($v_d, ['currency'])))}
              {/capture}
              {=og_include('compose/Inline.latte', ['class' => 'text-base font-bold', 'children' => (string) $c_6])|noescape}
              {capture $c_7}
                {=og_text(og_get($v_labels, ['open']))}
                {=og_include('icons/LucideIcon.latte', ['name' => 'arrow-right', 'size' => 16])|noescape}
              {/capture}
              {=og_include('compose/Inline.latte', ['class' => 'flex items-center gap-2 text-sm text-primary', 'children' => (string) $c_7])|noescape}
            {/capture}
            {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'justify' => 'between', 'children' => (string) $c_8])|noescape}
          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '2', 'children' => (string) $c_9])|noescape}
        {/capture}
        {=og_include('compose/Link.latte', ['href' => og_url(og_s(og_coalesce([og_get($v_d, ['href']), og_tpl('#/dish/{0}', [og_get($v_d, ['id'])])]))), 'variant' => 'block', 'class' => 'group flex-col items-stretch gap-4', 'attrs' => og_attrs(['data-slot', 'item']), 'children' => (string) $c_10])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => og_s((og_t(og_eq($v_cols, '4')) ? '2-4' : '1-3')), 'class' => 'gap-8', 'attrs' => og_attrs(['data-slot', 'items']), 'children' => (string) $c_11])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_12)])|noescape}
